static void *worker(void *arg) {
    struct queue *q = arg;
    for (;;) {
        pthread_mutex_lock(&q->m);
        while (q->count == 0) pthread_cond_wait(&q->not_empty, &q->m);
        job_t j = q->buf[q->tail++ % q->cap]; q->count--;
        pthread_cond_signal(&q->not_full);
        pthread_mutex_unlock(&q->m);
        handle(&j);                        /* process OUTSIDE the lock */
    }
}
/* start N workers on the SAME queue: pthread_create(&t[i], NULL, worker, q); */

