    pthread_create(&t[i], NULL, worker, (void *)(intptr_t)q);

void *worker(void *arg) {
    mqd_t q = (mqd_t)(intptr_t)arg;
    char buf[MSG_SIZE]; unsigned prio; ssize_t len;
    while ((len = mq_receive(q, buf, sizeof buf, &prio)) >= 0)
        handle(buf, (size_t)len);      /* exactly one receiver got it */
    return NULL;
}
